def same_component_check(grid, r1, c1, r2, c2):
    """Check if boundary cells at (r1,c1) and (r2,c2) belong to the same connected component of boundary color"""
    boundary_val = 4
    visited = [[False]*len(grid[0]) for _ in range(len(grid))]

    # Find all boundary cells in component containing (r1,c1)
    component = []
    q = [(r1, c1)]
    while q:
        cr, cc = q.pop(0)
        if visited[cr][cc] or grid[cr][cc] != boundary_val:
            continue
        visited[cr][cc] = True
        component.append((cr, cc))
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1),(0,0)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                q.append((nr, nc))

    # Check if (r2,c2) is in the component (or would be reached)
    # Actually let's do a cleaner BFS
    visited2 = [[False]*len(grid[0]) for _ in range(len(grid))]
    visited2[r1][c1] = True

    q = [(r1, c1)]
    while q:
        cr, cc = q.pop(0)
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if not visited2[nr][nc] and grid[nr][nc] == boundary_val:
                    visited2[nr][nc] = True
                    q.append((nr, nc))

    return visited2[r2][c2] and grid[r2][c2] == boundary_val

