def is_reachable_to_edge(grid, r, c, edge_color):
    """Check if a cell can reach an edge through the specified color"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    q = [(r, c)]

    while q:
        cr, cc = q.pop(0)
        if (cr, cc) in visited:
            continue
        visited.add((cr, cc))

        # Check if we're at an edge
        if cr == 0 or cr == rows - 1 or cc == 0 or cc == cols - 1:
            return True

        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == edge_color and (nr, nc) not in visited:
                    q.append((nr, nc))

    # Check if any visited cell is at edge
    for v in visited:
        if v[0] == 0 or v[0] == rows - 1 or v[1] == 0 or v[1] == cols - 1:
            return True
    return False

