# Let me check reachability separately for each color type
# Maybe "background" for reachability is the actual boundary color (4)?

def flood_from_boundary_through_bg(grid):
    """Find cells reachable from grid boundary through non-boundary colors"""
    from collections import deque

    boundary_val = 4
    bg_val = 8  # Actually background 
    rows, cols = len(grid), len(grid[0])
    reachable = [[False]*cols for _ in range(rows)]

    # Start from all grid edge cells that are NOT boundary color
    q = deque()
    for c in range(cols):
        if grid[0][c] != boundary_val:
            reachable[0][c] = True
            q.append((0, c))
        if grid[rows-1][c] != boundary_val:
            reachable[rows-1][c] = True
            q.append((rows-1, c))
    for r in range(rows):
        if grid[r][0] != boundary_val:
            reachable[r][0] = True
            q.append((r, 0))
        if grid[r][cols-1] != boundary_val:
            reachable[r][cols-1] = True
            q.append((r, cols-1))

    while q:
        r, c = q.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not reachable[nr][nc] and grid[nr][nc] != boundary_val:
                    reachable[nr][nc] = True
                    q.append((nr, nc))

    return reachable

