# Fix the deque bug - need tuple unpacking
def count_boundary_components(grid):
    """Count connected components of the boundary color"""
    from collections import deque

    boundary_val = None
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            color = grid[r][c]
            if color != 7:  # 7 is background
                boundary_val = color
                break
        if boundary_val:
            break

    visited = [[False]*len(grid[0]) for _ in range(len(grid))]
    components = 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if visited[r][c] or grid[r][c] != boundary_val:
                continue
            components += 1
            q = deque()
            q.append((r, c))
            while q:
                curr = q.popleft()
                cr, cc = curr
                if visited[cr][cc] or grid[cr][cc] != boundary_val:
                    continue
                visited[cr][cc] = True
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        q.append((nr, nc))
    return components

