    background = max(bg_count, key=bg_count.get)

    color_counts = Counter()
    for row in grid:
        for val in row:
            if val != background:
                color_counts[val] += 1
    boundary_pairs = []
    for val, cnt in color_counts.items():
        if cnt > 0:
            boundary_pairs.append(val)

    result = [row[:] for row in grid]

    for r in range(len(grid)):
        # Find all boundary cells in this row
        row_bg = background
        boundary_in_row = [c for c in range(len(grid[0])) if grid[r][c] != row_bg]

        if len(boundary_in_row) >= 2:
            # Everything between min and max boundary in this row should change
            min_c, max_c = min(boundary_in_row), max(boundary_in_row)
            for c in range(min_c + 1, max_c):
                if grid[r][c] == row_bg:
                    result[r][c] = 2

    return result

