# Let me now define the final rule and test it

def transform_rule_final(grid):
    """
    For each row, if the row contains at least 2 non-background cells,
    fill all background cells strictly between the leftmost and rightmost
    non-background cells with 2.

    For each column, if the column contains at least 2 non-background cells,
    fill all background cells strictly between the topmost and bottommost
    non-background cells with 2.

    This rule handles both demo 1 and demo 2.
    """
    from collections import Counter

    rows = len(grid)
    cols = len(grid[0])
    background = None

    # Find background color (most frequent)
    bg_counts = Counter()
    for r in range(rows):
        for c in range(cols):
            bg_counts[grid[r][c]] += 1
    background = max(bg_counts.most_common(), key=lambda x: x[1])[0]

    result = [row[:] for row in grid]

    # Apply horizontal fill for each row
    for r in range(rows):
        non_bg_cols = [c for c in range(cols) if grid[r][c] != background]
        if len(non_bg_cols) >= 2:
            min_c, max_c = min(non_bg_cols), max(non_bg_cols)
            for c in range(min_c + 1, max_c):
                if grid[r][c] == background:
                    result[r][c] = 2

    # Apply vertical fill for each column
    for c in range(cols):
        non_bg_rows = [r for r in range(rows) if grid[r][c] != background]
        if len(non_bg_rows) >= 2:
            min_r, max_r = min(non_bg_rows), max(non_bg_rows)
            for r in range(min_r + 1, max_r):
                if grid[r][c] == background:
                    result[r][c] = 2

    return result

