def transform_between_boundary_segments(grid):
    """
    For each row and column, identify segments of non-background cells.
    Fill background cells that are strictly between two such segments with 2.
    """
    from collections import Counter

    rows = len(grid)
    cols = len(grid[0])

    # Find background color
    bg_count = {}
    for r in range(rows):
        for c in range(cols):
            bg_count[grid[r][c]] += 1
    background = max(bg_count, key=bg_count.get)

    result = [row[:] for row in grid]

    # For each row: find segments of non-background and fill between them
    for r in range(rows):
        # Find positions of non-background cells
        non_bg_positions = [c for c in range(cols) if grid[r][c] != background]

        # Group into contiguous segments
        segments = []
        for c in non_bg_positions:
            if not segments or c == segments[-1][1] + 1:
                segments[-1].append(c)
            else:
                segments.append([c, c])

        # Fill background cells between segments
        for i in range(len(segments) - 1):
            seg_left = segments[i][0]
            seg_right_start = segments[i + 1][0]
            # Background cells from (seg_left + 1) to (seg_right_start - 1)
            for c in range(seg_left + 1, seg_right_start):
                if grid[r][c] == background:
                    result[r][c] = 2

    # For each column: same logic
    for c in range(cols):
        non_bg_positions = [r for r in range(rows) if grid[r][c] != background]

        segments = []
        for r in non_bg_positions:
            if not segments or r == segments[-1][1] + 1:
                segments[-1].append(r)
            else:
                segments.append([r, r])

        for i in range(len(segments) - 1):
            seg_top = segments[i][0]
            seg_bottom_start = segments[i + 1][0]
            for r in range(seg_top + 1, seg_bottom_start):
                if grid[r][c] == background:
                    result[r][c] = 2

    return result

