def build_expected_from_counts(grid, bg, threshold):
    rows = len(grid)
    cols = len(grid[0])
    col_counts = [sum(1 for r in range(rows) if grid[r][c] != bg) for c in range(cols)]
    row_counts = [sum(1 for c in range(cols) if grid[r][c] != bg) for r in range(rows)]

    expected = [[False]*cols for _ in range(rows)]
    max_count = max(max(row_counts), max(col_counts))
    threshold = int(max_count * max(0.5, max_count / (rows + cols)))

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg:
                if row_counts[r] >= threshold and col_counts[c] >= threshold:
                    expected[r][c] = True
    return expected

def fill_expected_gaps(grid, expected, background):
    result = [row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == background and expected[r][c]:
                result[r][c] = 2
    return result

