# Test edge-of-bbox rule

def edge_of_bbox_fill_rule(grid):
    rows = len(grid)
    cols = len(grid[0])
    all_cells = [(r, c, grid[r][c]) for r in range(rows) for c in range(cols)]
    bg_counts = {}
    for r, c, val in all_cells:
        bg_counts[val] = bg_counts.get(val, 0) + 1
    background = max(bg_counts, key=bg_counts.get)

    # Find bbox of non-bg cells
    non_bg = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] != background]
    if not non_bg:
        return [row[:] for row in grid]

    min_r, max_r = min(c for r, c in non_bg), max(c for r, c in non_bg)
    min_c, max_c = min(r for r, c in non_bg), max(r for r, c in non_bg)

    result = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == background:
                # Check if at bbox edge
                at_bbox_edge = (r == min_r) or (r == max_r) or (c == min_c) or (c == max_c)

                if at_bbox_edge:
                    # Check if enclosed in perpendicular direction
                    # If at row edge (min_r or max_r), check for horizontal enclosure
                    # If at col edge (min_c or max_c), check for vertical enclosure

                    if (r == min_r) or (r == max_r):
                        # At row edge, check horizontal enclosure
                        has_left = any(grid[r][lc] != background for lc in range(c-1, -1, -1))
                        has_right = any(grid[r][rc] != background for rc in range(c+1, cols))
                        if has_left and has_right:
                            result[r][c] = 2
                    elif (c == min_c) or (c == max_c):
                        # At col edge, check vertical enclosure
                        has_up = any(grid[ur][c] != background for ur in range(r-1, -1, -1))
                        has_down = any(grid[dr][c] != background for dr in range(r+1, rows))
                        if has_up and has_down:
                            result[r][c] = 2

    return result

