# Let me analyze the structure differently by finding all "segments"
# A segment is a consecutive run of the same color

def find_segments(grid, color, include_horizontal=True, include_vertical=True):
    rows = len(grid)
    cols = len(grid[0])
    segments = []

    if include_horizontal:
        for r in range(rows):
            c = 0
            while c < cols:
                start = c
                while c < cols and grid[r][c] == color:
                    c += 1
                end = c
                if end - start > 1:  # At least 2 cells
                    segments.append(('H', r, start, end, color))
                else:
                    c += 1

    if include_vertical:
        for c in range(cols):
            r = 0
            while r < rows:
                start = r
                while r < rows and grid[r][c] == color:
                    r += 1
                end = r
                if end - start > 1:
                    segments.append(('V', c, start, end, color))

    return segments

